// Filter pages updated within LOOKBACK_MIN
const lookbackMin = $('⚙️ Config').first().json.LOOKBACK_MIN || 65;
const cutoff = new Date(Date.now() - lookbackMin * 60 * 1000);

const results = $input.first().json.results || [];

const recent = results.filter(page => {
  const edited = new Date(page.last_edited_time);
  return edited >= cutoff;
});

if (recent.length === 0) {
  // No updates — return empty to stop execution
  return [];
}

return recent.map(page => ({
  json: {
    pageId: page.id,
    title: page.properties?.title?.title?.[0]?.plain_text ||
           page.properties?.Name?.title?.[0]?.plain_text ||
           page.title?.[0]?.plain_text ||
           'Untitled',
    lastEdited: page.last_edited_time,
    url: page.url,
    GITHUB_OWNER: $('⚙️ Config').first().json.GITHUB_OWNER,
    GITHUB_REPO: $('⚙️ Config').first().json.GITHUB_REPO,
    SYNC_FOLDER: $('⚙️ Config').first().json.SYNC_FOLDER,
    BRANCH: $('⚙️ Config').first().json.BRANCH
  }
}));

// Convert Notion blocks to Markdown
const page = $('🔄 Loop Pages').first().json;
const blocks = $input.first().json.results || [];

function richText(arr) {
  if (!arr || arr.length === 0) return '';
  return arr.map(rt => {
    let t = rt.plain_text || '';
    const a = rt.annotations || {};
    if (a.code) t = `\`${t}\``;
    if (a.bold) t = `**${t}**`;
    if (a.italic) t = `*${t}*`;
    if (a.strikethrough) t = `~~${t}~~`;
    if (rt.href) t = `[${t}](${rt.href})`;
    return t;
  }).join('');
}

function blocksToMd(blocks) {
  let md = '';
  let numCounter = 0;
  for (const b of blocks) {
    if (b.type !== 'numbered_list_item') numCounter = 0;
    switch (b.type) {
      case 'paragraph':
        const p = richText(b.paragraph?.rich_text);
        md += p ? `${p}\n\n` : '\n';
        break;
      case 'heading_1':
        md += `# ${richText(b.heading_1?.rich_text)}\n\n`;
        break;
      case 'heading_2':
        md += `## ${richText(b.heading_2?.rich_text)}\n\n`;
        break;
      case 'heading_3':
        md += `### ${richText(b.heading_3?.rich_text)}\n\n`;
        break;
      case 'bulleted_list_item':
        md += `- ${richText(b.bulleted_list_item?.rich_text)}\n`;
        break;
      case 'numbered_list_item':
        numCounter++;
        md += `${numCounter}. ${richText(b.numbered_list_item?.rich_text)}\n`;
        break;
      case 'to_do':
        const chk = b.to_do?.checked ? 'x' : ' ';
        md += `- [${chk}] ${richText(b.to_do?.rich_text)}\n`;
        break;
      case 'code':
        const lang = b.code?.language || '';
        md += `\`\`\`${lang}\n${richText(b.code?.rich_text)}\n\`\`\`\n\n`;
        break;
      case 'quote':
        md += `> ${richText(b.quote?.rich_text)}\n\n`;
        break;
      case 'callout':
        const icon = b.callout?.icon?.emoji || '';
        md += `> ${icon} ${richText(b.callout?.rich_text)}\n\n`;
        break;
      case 'divider':
        md += `---\n\n`;
        break;
      case 'image':
        const imgUrl = b.image?.external?.url || b.image?.file?.url || '';
        const cap = richText(b.image?.caption);
        md += `![${cap}](${imgUrl})\n\n`;
        break;
      case 'child_page':
        md += `- [[${b.child_page?.title}]]\n`;
        break;
      case 'toggle':
        md += `<details><summary>${richText(b.toggle?.rich_text)}</summary>\n\n</details>\n\n`;
        break;
      case 'table_of_contents':
        break;
      default:
        break;
    }
  }
  return md.trim();
}

// Build sanitized filename
const sanitizeFilename = (title) => {
  return title
    .replace(/[/\\:*?"<>|]/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_{2,}/g, '_')
    .substring(0, 100);
};

const notionId = page.pageId.replace(/-/g, '');
const filename = sanitizeFilename(page.title);
const filePath = `${page.SYNC_FOLDER}/${filename}.md`;

// Build frontmatter block
const header = `# ${page.title}\n\n- **Notion ID:** ${notionId}\n- **URL:** ${page.url}\n- **Last Edited:** ${page.lastEdited}\n\n---\n\n`;

const body = blocksToMd(blocks);
const fullContent = header + body;

return [{
  json: {
    filePath,
    filename: `${filename}.md`,
    content: fullContent,
    contentBase64: Buffer.from(fullContent).toString('base64'),
    commitMessage: `sync: ${page.title}`,
    GITHUB_OWNER: page.GITHUB_OWNER,
    GITHUB_REPO: page.GITHUB_REPO,
    BRANCH: page.BRANCH
  }
}];

// Merge markdown data + existing file SHA (for update)
const md = $('✨ Blocks → Markdown').first().json;
const ghResponse = $input.first().json;

// SHA is required when updating an existing file
const sha = ghResponse?.sha || null;

return [{
  json: {
    ...md,
    sha
  }
}];
